def parse_dat_coords(filepath):
    coords = []
    with open(filepath) as f:
        for line in f:
            line = line.strip()
            if not line or line[0] in ("t", "b", "E"):
                continue
            vals = line.split()
            if len(vals) < 3:
                continue
            try:
                coords.append([float(vals[0]), float(vals[1]), float(vals[2])])
            except ValueError:
                continue
    return coords

def com(coords, indices):
    pts = [coords[i] for i in indices]
    n = len(pts)
    return [sum(p[k] for p in pts) / n for k in range(3)]

def dist(a, b):
    return math.sqrt(sum((a[k]-b[k])**2 for k in range(3)))

